using System.IO;
using System.Text.Json;
using VisionPlugins.Calibration;
try {
const string folder="analysis/map-calibration/image-grid-pruning-trace";var report=new List<object>();long totalFields=0,totalExact=0;bool failed=false;
foreach(string line in File.ReadLines(folder+"/pruning-trace.jsonl")){
 using var document=JsonDocument.Parse(line);var row=document.RootElement;int sequence=row.GetProperty("sequence").GetInt32();string prefix=$"{folder}/pruning-{sequence:D3}-";
 byte[] bytes=File.ReadAllBytes(prefix+"candidates.bin");var candidates=new List<NImageSourceCandidate>();for(int i=0;i<bytes.Length;i+=28)candidates.Add(new(BitConverter.ToSingle(bytes,i),BitConverter.ToSingle(bytes,i+4),BitConverter.ToInt32(bytes,i+8),BitConverter.ToSingle(bytes,i+12),BitConverter.ToSingle(bytes,i+16),BitConverter.ToSingle(bytes,i+20),BitConverter.ToSingle(bytes,i+24)));
 int[] Ints(string suffix){var b=File.ReadAllBytes(prefix+suffix+".bin");var values=new int[b.Length/4];Buffer.BlockCopy(b,0,values,0,b.Length);return values;}
 var state=new NImageSourceGridState{Count=row.GetProperty("beforeCount").GetInt32(),Width=row.GetProperty("dimensions")[0].GetInt32(),Height=row.GetProperty("dimensions")[1].GetInt32()};Ints("indices-entry").CopyTo(state.Indices,0);var used=Ints("used-entry");var scoreBytes=File.ReadAllBytes(prefix+"scores-entry.bin");Buffer.BlockCopy(scoreBytes,0,state.Scores,0,scoreBytes.Length);var targets=Ints("targets-entry");int targetCount=row.GetProperty("beforeTargetCount").GetInt32();float threshold=BitConverter.Int32BitsToSingle((int)row.GetProperty("beforeThresholdBits").GetUInt32());
 NImageSourceGridPruning.Prune(candidates,used,state,targets,ref targetCount,ref threshold);var expectedUsed=Ints("used-return");var expectedIndices=Ints("indices-return");var expectedTargets=Ints("targets-return");var expectedScores=File.ReadAllBytes(prefix+"scores-return.bin");int flags=0,indices=0,scores=0,coords=0;var differences=new List<object>();
 for(int i=0;i<90000;i++){if(used[i]==expectedUsed[i])flags++;else if(differences.Count<12)differences.Add(new{kind="used",i,actual=used[i],expected=expectedUsed[i]});if(state.Indices[i]==expectedIndices[i])indices++;else if(differences.Count<12)differences.Add(new{kind="index",i,actual=state.Indices[i],expected=expectedIndices[i]});}
 for(int i=0;i<state.Scores.Length;i++){int actual=BitConverter.SingleToInt32Bits(state.Scores[i]),expected=BitConverter.ToInt32(expectedScores,i*4);if(actual==expected)scores++;else if(differences.Count<12)differences.Add(new{kind="score",i,actual,expected});}for(int i=0;i<targets.Length;i++)if(targets[i]==expectedTargets[i])coords++;
 bool meta=state.Count==row.GetProperty("count").GetInt32()&&targetCount==row.GetProperty("targetCount").GetInt32()&&(uint)BitConverter.SingleToInt32Bits(threshold)==row.GetProperty("thresholdBits").GetUInt32();bool success=meta&&flags==90000&&indices==90000&&scores==270000&&coords==targets.Length;failed|=!success;totalFields+=450003+targets.Length;totalExact+=flags+indices+scores+coords+(meta?3:0);report.Add(new{sequence,state.Count,expectedCount=row.GetProperty("count").GetInt32(),targetCount,expectedTargetCount=row.GetProperty("targetCount").GetInt32(),thresholdBits=(uint)BitConverter.SingleToInt32Bits(threshold),expectedThresholdBits=row.GetProperty("thresholdBits").GetUInt32(),flags,indices,scores,coords,success,differences});if(!success)Console.WriteLine($"Pruning{sequence}: count{state.Count}/{row.GetProperty("count")}, targets{targetCount}/{row.GetProperty("targetCount")}, flags{flags}, indices{indices}, scores{scores}, coords{coords}");
}
Directory.CreateDirectory("analysis/map-calibration/grid-pruning");File.WriteAllText("analysis/map-calibration/grid-pruning/comparison.json",JsonSerializer.Serialize(new{cases=report.Count,totalFields,totalExact,failed,report},new JsonSerializerOptions{WriteIndented=true}));if(failed||report.Count!=64)throw new Exception("Original grid pruning differs");Console.WriteLine($"Native pruning: {report.Count} cases/{totalExact} fields exact");return 0;
}catch(Exception error){Console.Error.WriteLine(error);return 1;}
